// Guard FU 4h: para cada caso pending, descartar si:
//   1. Existe Turn 2+ en pipeline para ese smartlead_lead_id (lead ya
//      respondio Y nosotros ya generamos algo despues)
//   2. Lead tiene reunion programada en HubSpot (futura o ultimos 7 dias)
//
// Tolerante a errores de API (HubSpot fail-open: si no podemos verificar,
// dejamos pasar el FU. Es preferible un FU innecesario a no enviar nunca).

const pendingItems = $input.all();
if (pendingItems.length === 0) return [];

const slLeadIds = [...new Set(pendingItems.map(i => i.json.smartlead_lead_id).filter(Boolean))];

// 1. Bulk lookup en Supabase: turn2+ rows para estos lead ids
let leadsWithTurn2 = new Set();
try {
  const subProjUrl = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline';
  const params = new URLSearchParams({
    select: 'smartlead_lead_id,turn_number',
    smartlead_lead_id: 'in.(' + slLeadIds.map(id => '"' + id + '"').join(',') + ')',
    turn_number: 'gt.1',
    limit: '500',
  });
  const resp = await this.helpers.httpRequestWithAuthentication.call(
    this, 'supabaseApi',
    { method: 'GET', url: subProjUrl + '?' + params.toString(), json: true }
  );
  const rows = Array.isArray(resp) ? resp : [];
  rows.forEach(r => leadsWithTurn2.add(String(r.smartlead_lead_id)));
} catch (e) {
  // Si Supabase falla, fail-closed (no envies — no sabemos)
  return [{ json: { _wf03_aborted: true, reason: 'supabase lookup failed: ' + (e.message || e) } }];
}

// 2. Para cada item: chequear HubSpot meetings (futuras o recientes)
const out = [];
for (const item of pendingItems) {
  const row = item.json;
  const slId = String(row.smartlead_lead_id);
  const hsContactId = row.hubspot_contact_id;

  if (leadsWithTurn2.has(slId)) {
    // Ya hay un Turn 2+ — saltar
    continue;
  }

  let hasMeeting = false;
  if (hsContactId) {
    try {
      const meetings = await this.helpers.httpRequestWithAuthentication.call(
        this, 'hubspotAppToken',
        {
          method: 'GET',
          url: 'https://api.hubapi.com/crm/v3/objects/contacts/' + encodeURIComponent(hsContactId) + '/associations/meetings',
          json: true,
        }
      );
      const meetingIds = (meetings.results || []).map(r => r.id).slice(0, 20);
      if (meetingIds.length > 0) {
        const batch = await this.helpers.httpRequestWithAuthentication.call(
          this, 'hubspotAppToken',
          {
            method: 'POST',
            url: 'https://api.hubapi.com/crm/v3/objects/meetings/batch/read',
            body: {
              properties: ['hs_meeting_start_time', 'hs_meeting_outcome'],
              inputs: meetingIds.map(id => ({ id })),
            },
            json: true,
          }
        );
        const now = Date.now();
        const sevenDaysAgo = now - (7 * 24 * 60 * 60 * 1000);
        hasMeeting = (batch.results || []).some(m => {
          const t = m.properties && m.properties.hs_meeting_start_time
            ? Date.parse(m.properties.hs_meeting_start_time) : 0;
          // Reunion futura O en los ultimos 7 dias
          return t > now || (t >= sevenDaysAgo && t <= now);
        });
      }
    } catch (e) {
      // Fail-open: si HubSpot falla, no skipear (mejor un FU innecesario que perdido)
    }
  }

  if (hasMeeting) continue;
  out.push({ json: row });
}

return out;
